effect.shader:
void main(){
vec2 uv=acScreenNorm,dir=vec2(cos(direction),sin(direction));
vec4 src=texture2DCv(inputImg.texture,uv); float lum=dot(src.rgb,vec3(0.299,0.587,0.114));
vec2 q=clamp(uv-dir*depth*(lum-0.35),0.0,1.0);
vec4 base=texture2DCv(inputImg.texture,q);
float scan=pow(0.5+0.5*sin((q.y+lum*depth)*scanDensity+phase),12.0);
float slice=pow(0.5+0.5*cos((lum+dot(q,dir)*depth)*scanDensity*0.42-phase),18.0);
vec4 r=texture2DCv(inputImg.texture,clamp(q+dir*depth*0.22,0.0,1.0));
vec4 b=texture2DCv(inputImg.texture,clamp(q-dir*depth*0.22,0.0,1.0));
vec3 spectral=vec3(r.r,base.g,b.b);
vec3 hologram=mix(spectral,spectral*holoColor.rgb,0.72);
hologram+=holoColor.rgb*(scan*0.55+slice*0.35)*glow*base.a;
hologram*=0.72+0.38*lum;
gl_FragColor=vec4(mix(src.rgb,hologram,mixAmount),src.a);
}
